CREATE TABLE product (id VARCHAR(40) PRIMARY KEY, name VARCHAR(100) NOT NULL, icon VARCHAR(30) NOT NULL, application VARCHAR(200) NOT NULL);
CREATE TABLE file_asset (id VARCHAR(40) PRIMARY KEY, product_id VARCHAR(40) NOT NULL REFERENCES product(id), original_name VARCHAR(255) NOT NULL, storage_name VARCHAR(100) NOT NULL, sha256 VARCHAR(64) NOT NULL, size_bytes BIGINT NOT NULL, created_by VARCHAR(100) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE review_dataset (id VARCHAR(40) PRIMARY KEY, product_id VARCHAR(40) NOT NULL REFERENCES product(id), chain VARCHAR(10) NOT NULL, state VARCHAR(20) NOT NULL, raw_coverage VARCHAR(15) NOT NULL, risk_coverage VARCHAR(15) NOT NULL, source_as_of VARCHAR(40) NOT NULL, raw_as_of VARCHAR(40) NOT NULL, risk_as_of VARCHAR(40) NOT NULL, asset_id VARCHAR(40) REFERENCES file_asset(id), base_dataset_id VARCHAR(40), created_at VARCHAR(40) NOT NULL);
CREATE TABLE source_auth (id VARCHAR(40) PRIMARY KEY, dataset_id VARCHAR(40) NOT NULL REFERENCES review_dataset(id), record_key VARCHAR(1000) NOT NULL, employee_id VARCHAR(150), user_name VARCHAR(150), department VARCHAR(1000), dept_code VARCHAR(100), person_kind VARCHAR(50), employment_class VARCHAR(50), user_namespace VARCHAR(100), user_key VARCHAR(64) NOT NULL, permission_name VARCHAR(400), role_id VARCHAR(150), role_type VARCHAR(100), permission_type VARCHAR(100), description TEXT, start_at VARCHAR(40), expires_at VARCHAR(40), authorization_id VARCHAR(200), application VARCHAR(200), app_id VARCHAR(150), tenant_id VARCHAR(150), source_system VARCHAR(100), source_asset_id VARCHAR(40), source_sheet VARCHAR(200), source_row INTEGER, base_row_id VARCHAR(40), record_version INTEGER NOT NULL, UNIQUE(dataset_id,record_key));
CREATE TABLE source_point (id VARCHAR(40) PRIMARY KEY, dataset_id VARCHAR(40) NOT NULL REFERENCES review_dataset(id), record_key VARCHAR(1000) NOT NULL, role_name VARCHAR(400), role_id VARCHAR(150), role_type VARCHAR(100), set_name VARCHAR(400), set_id VARCHAR(150), point_name VARCHAR(600), point_id VARCHAR(200), resource_type VARCHAR(100), subtype VARCHAR(100), confidence DECIMAL(8,6), evidence TEXT, application VARCHAR(200), app_id VARCHAR(150), tenant_id VARCHAR(150), source_system VARCHAR(100), source_asset_id VARCHAR(40), source_sheet VARCHAR(200), source_row INTEGER, base_row_id VARCHAR(40), record_version INTEGER NOT NULL, UNIQUE(dataset_id,record_key));
CREATE TABLE risk_finding (id VARCHAR(40) PRIMARY KEY, dataset_id VARCHAR(40) NOT NULL REFERENCES review_dataset(id), chain VARCHAR(10) NOT NULL, rule_code VARCHAR(20) NOT NULL, check_name VARCHAR(400), risk VARCHAR(10) NOT NULL, workflow VARCHAR(30) NOT NULL, violation TEXT, advice TEXT, evidence TEXT, confidence DECIMAL(8,6), audited_source_id VARCHAR(40), current_source_id VARCHAR(40), link_status VARCHAR(30) NOT NULL, base_finding_id VARCHAR(40), source_asset_id VARCHAR(40), source_sheet VARCHAR(200), source_row INTEGER, record_version INTEGER NOT NULL);
CREATE TABLE user_role_finding (finding_id VARCHAR(40) PRIMARY KEY REFERENCES risk_finding(id), employee_id VARCHAR(150), user_name VARCHAR(150), department VARCHAR(1000), permission_name VARCHAR(400), role_id VARCHAR(150), role_type VARCHAR(100), permission_type VARCHAR(100), description TEXT, start_at VARCHAR(40), expires_at VARCHAR(40), authorization_id VARCHAR(200), application VARCHAR(200), app_id VARCHAR(150), tenant_id VARCHAR(150), source_system VARCHAR(100));
CREATE TABLE matrix_finding (finding_id VARCHAR(40) PRIMARY KEY REFERENCES risk_finding(id), role_name VARCHAR(400), role_id VARCHAR(150), role_type VARCHAR(100), set_name VARCHAR(400), set_id VARCHAR(150), point_name VARCHAR(600), point_id VARCHAR(200), resource_type VARCHAR(100), subtype VARCHAR(100), application VARCHAR(200), app_id VARCHAR(150), tenant_id VARCHAR(150), source_system VARCHAR(100));
CREATE TABLE product_release (id VARCHAR(40) PRIMARY KEY, product_id VARCHAR(40) NOT NULL REFERENCES product(id), user_dataset_id VARCHAR(40) REFERENCES review_dataset(id), matrix_dataset_id VARCHAR(40) REFERENCES review_dataset(id), base_release_id VARCHAR(40), published_by VARCHAR(100) NOT NULL, published_at VARCHAR(40) NOT NULL, reason TEXT NOT NULL, release_number INTEGER NOT NULL);
CREATE TABLE product_publication (product_id VARCHAR(40) PRIMARY KEY REFERENCES product(id), release_id VARCHAR(40) REFERENCES product_release(id), revision INTEGER NOT NULL);
CREATE TABLE review_draft (id VARCHAR(40) PRIMARY KEY, product_id VARCHAR(40) NOT NULL REFERENCES product(id), base_release_id VARCHAR(40), base_revision INTEGER NOT NULL, user_dataset_id VARCHAR(40), matrix_dataset_id VARCHAR(40), state VARCHAR(20) NOT NULL, created_by VARCHAR(100) NOT NULL, created_at VARCHAR(40) NOT NULL, revision INTEGER NOT NULL);
CREATE TABLE import_job (id VARCHAR(40) PRIMARY KEY, product_id VARCHAR(40) NOT NULL REFERENCES product(id), asset_id VARCHAR(40) NOT NULL REFERENCES file_asset(id), draft_id VARCHAR(40), base_release_id VARCHAR(40), base_revision INTEGER NOT NULL, mode VARCHAR(20) NOT NULL, raw_coverage VARCHAR(15) NOT NULL, risk_coverage VARCHAR(15) NOT NULL, source_as_of VARCHAR(40) NOT NULL, status VARCHAR(20) NOT NULL, progress INTEGER NOT NULL, errors TEXT, preview TEXT, created_by VARCHAR(100) NOT NULL, created_at VARCHAR(40) NOT NULL, lease_until VARCHAR(40), lease_owner VARCHAR(40), attempts INTEGER NOT NULL, request_key VARCHAR(100) NOT NULL, request_digest VARCHAR(64) NOT NULL, UNIQUE(created_by,product_id,request_key));
CREATE TABLE snapshot (id VARCHAR(40) PRIMARY KEY, scope_hash VARCHAR(64) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE snapshot_entry (snapshot_id VARCHAR(40) NOT NULL REFERENCES snapshot(id), product_id VARCHAR(40) NOT NULL REFERENCES product(id), release_id VARCHAR(40), PRIMARY KEY(snapshot_id,product_id));
CREATE TABLE audit_event (id VARCHAR(40) PRIMARY KEY, product_id VARCHAR(40) NOT NULL REFERENCES product(id), actor VARCHAR(100) NOT NULL, action VARCHAR(50) NOT NULL, target_id VARCHAR(100) NOT NULL, before_value TEXT, after_value TEXT, reason TEXT NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE publish_request (actor VARCHAR(100) NOT NULL, product_id VARCHAR(40) NOT NULL, request_key VARCHAR(100) NOT NULL, request_digest VARCHAR(64) NOT NULL, release_id VARCHAR(40) NOT NULL REFERENCES product_release(id), PRIMARY KEY(actor,product_id,request_key));
CREATE TABLE export_job (id VARCHAR(40) PRIMARY KEY, snapshot_id VARCHAR(40) NOT NULL REFERENCES snapshot(id), product_id VARCHAR(40) REFERENCES product(id), chain VARCHAR(10), query_json TEXT NOT NULL, status VARCHAR(20) NOT NULL, storage_name VARCHAR(100), errors TEXT, created_by VARCHAR(100) NOT NULL, created_at VARCHAR(40) NOT NULL, lease_until VARCHAR(40), lease_owner VARCHAR(40), request_key VARCHAR(100) NOT NULL, request_digest VARCHAR(64) NOT NULL, UNIQUE(created_by,request_key));
CREATE INDEX ix_finding_dataset ON risk_finding(dataset_id,chain,risk,workflow,id);
CREATE INDEX ix_finding_rule ON risk_finding(dataset_id,rule_code,risk);
CREATE INDEX ix_auth_user ON source_auth(dataset_id,user_namespace,employee_id);
CREATE INDEX ix_point_bind ON source_point(dataset_id,point_id);
CREATE INDEX ix_event_product ON audit_event(product_id,created_at);
CREATE INDEX ix_import_claim ON import_job(status,lease_until,created_at);
CREATE INDEX ix_export_claim ON export_job(status,lease_until,created_at);
